use std::{fs,path::{Path,PathBuf}};use serde_json::{json,Value};
fn id_valid(id:&str)->bool{id.len()==32&&id.bytes().all(|c|c.is_ascii_digit()||(b'a'..=b'f').contains(&c))}
fn batch_valid(name:&str)->bool{name.strip_prefix("batch-").is_some_and(id_valid)}
fn batches(root:&Path)->Vec<PathBuf>{let mut out=Vec::new();if let Ok(entries)=fs::read_dir(root){for e in entries.flatten(){let name=e.file_name();let name=name.to_string_lossy();if batch_valid(&name)&&e.file_type().is_ok_and(|t|t.is_dir()&&!t.is_symlink()){let marker=e.path().join(".atlas-import-batch");if !marker.is_symlink()&&fs::read(&marker).ok().as_deref()==Some(b"atlas-import-v1"){out.push(e.path())}}}}out.sort();out}
pub fn resolve(root:&Path,default:&Path,id:&str)->PathBuf{if id=="default"{return default.to_owned()}let direct=root.join(id);if !id_valid(id)||direct.exists()||direct.is_symlink(){return direct}for batch in batches(root){let candidate=batch.join(id);if candidate.exists()||candidate.is_symlink(){return candidate}}direct}
pub fn append(root:&Path,items:&mut Vec<Value>){for batch in batches(root){let Ok(entries)=fs::read_dir(batch)else{continue};let mut entries:Vec<_>=entries.flatten().collect();entries.sort_by_key(|e|e.file_name());for entry in entries{let id=entry.file_name().to_string_lossy().to_string();if !id_valid(&id)||!entry.file_type().is_ok_and(|x|x.is_dir()&&!x.is_symlink()){continue}let path=entry.path();let marker=path.join(".workspace.json");if marker.is_symlink(){continue}if let Ok(data)=fs::read(marker){if let Ok(v)=serde_json::from_slice::<Value>(&data){if let Some(name)=v["name"].as_str(){items.push(json!({"id":id,"name":name,"protected":crate::protected::Protected::is_protected_dir(&path)}))}}}}}}
pub fn parent_allowed(root:&Path,dir:&Path)->bool{let Ok(root)=root.canonicalize()else{return false};let Some(parent)=dir.parent()else{return false};let Ok(real)=parent.canonicalize()else{return false};if real==root{return true}let Some(name)=parent.file_name().and_then(|n|n.to_str())else{return false};batch_valid(name)&&!parent.is_symlink()&&!parent.join(".atlas-import-batch").is_symlink()&&fs::read(parent.join(".atlas-import-batch")).ok().as_deref()==Some(b"atlas-import-v1")&&parent.parent().and_then(|p|p.canonicalize().ok()).as_ref()==Some(&root)}
